<?php
require "db.php"; require "functions.php";
$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn(); $error="";
if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$name=trim($_POST["full_name"]??"");$email=strtolower(trim($_POST["email"]??""));$cid=trim($_POST["college_id"]??"");$pw=$_POST["password"]??"";$confirm=$_POST["confirm_password"]??"";
 if($count>0)$error="An administrator already exists. Setup is disabled.";
 elseif($name===""||!filter_var($email,FILTER_VALIDATE_EMAIL)||$cid===""||strlen($pw)<12)$error="Complete all fields and use a password with at least 12 characters.";
 elseif($pw!==$confirm)$error="Passwords do not match.";
 else try{$q=$pdo->prepare("INSERT INTO users(full_name,email,college_id,password_hash,role,is_approved) VALUES(?,?,?,?,'admin',1)");$q->execute([$name,$email,$cid,password_hash($pw,PASSWORD_DEFAULT)]);flash("Administrator account created. Sign in with your new credentials.");header("Location: admin_login.php");exit;}catch(PDOException $e){$error="The email or administrator ID is already in use.";}
}
$title="Administrator setup";require "layout.php";?>
<section class="auth"><div class="auth-side"><div class="eyebrow">INITIAL SETUP</div><h1>Set up your<br><span>admin access.</span></h1><p>Create the first administrator account for this local CampusCare installation.</p></div><div class="auth-form"><div class="eyebrow">ADMINISTRATOR</div><h2>Create admin account</h2><p class="muted">This form is available only when no admin exists.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($count===0):?><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><label>Full name</label><input name="full_name" required><label>Administrator email</label><input name="email" type="email" required><label>Administrator ID</label><input name="college_id" required><label>Create password (12+ characters)</label><input name="password" type="password" minlength="12" required><label>Confirm password</label><input name="confirm_password" type="password" minlength="12" required><button class="btn btn-primary full">Create administrator ↗</button></form><?php else:?><div class="alert error">An admin account already exists. Use admin sign in.</div><?php endif;?><div class="links"><a href="admin_login.php">Administrator sign in</a></div></div></section><?php require "end.php";?>
